  'mixer.audio_proc_note': "В порядке прохождения сигнала: подстройка и полярность, уровень шума (вычитает постоянный шум под сигналом; добавляет 23 мс; для музыки запишите образец), фильтры высоких и низких частот, четыре полосы EQ, гейт, компрессор (одной ручкой или вручную), де-эссер, хорус, затем фейдер и панорама, а также посылы на реверберацию и задержку. Приглушение под речь снижает уровень этой дорожки, пока говорит микрофон, линейный вход, канал пульта или сетевой источник: включайте его на подложке или программе.",
