  'device.owner_provision.tip': "Настроить эту панель как владельца устройства (тихие обновления, перезагрузка, киоск, управление временем)",
  'device.owner_provision.title': "Настройка в качестве владельца устройства",
  'device.owner_provision.intro': "Режим владельца устройства — необязательное расширение, которое открывает тихие обновления, чистую перезагрузку, киоск-режим lock-task и управление временем. Подключите новую или сброшенную до заводских настроек панель по QR-коду или через ADB.",
  'device.owner_provision.qr_hint': "Сбросьте панель до заводских настроек, 6 раз нажмите на экран приветствия мастера настройки, затем отсканируйте этот код.",
  'device.owner_provision.adb_label': "Или через ADB (новое устройство, без аккаунтов, отладка по USB включена):",
  'device.owner_provision.copy': "Копировать",
