  'device.owner_provision.constraints': "Требуется только что настроенное или сброшенное до заводских настроек устройство без аккаунтов, до подключения других приложений владельца устройства. Если устройством уже управляет MDM, ScreenTinker остаётся на уровне Tier 0/1, а обновлениями управляет MDM.",
  'device.owner_provision.error': "Не удалось загрузить данные для настройки",
  'device.owner_provision.verified_from_apk': "Подпись проверена по текущему APK на сервере — она всегда совпадает с устанавливаемой сборкой.",
  'device.owner_provision.fallback_checksum': "На сервере пока нет APK — используется резервная контрольная сумма. Загрузите APK плеера перед настройкой.",
  'device.tier2.label': "Владелец устройства:",
