  'device.live_video.hint': "Показывает живой поток WebRTC в разделе «Сейчас играет», когда плеер его публикует. Также требуется, чтобы живое видео было включено для этого рабочего пространства и настроено на сервере. Иначе используются скриншоты.",
  'device.ignore_battery.toggle': "Питание от сети (игнорировать батарею)",
  'device.native_video.toggle': "Native 4K (аппаратный видеослой)",
  'device.native_video.hint': "Использует аппаратный видеослой дисплея для полноэкранного видео на поддерживаемых устройствах Android. Преобразует локальные изображения больше 1080p в зацикленный вариант H.264. Это позволяет показывать клипы и изображения 4K в полном разрешении на приставках, чей интерфейс рендерится в меньшем разрешении (Chromecast with Google TV, большинство ТВ-стиков). Если в информации об экране рядом с разрешением экрана указано меньшее разрешение «UI» (например, 3840x2160 (UI 1920x1080)), эта настройка поможет обойти ограничение. Элементы, показанные таким образом, появляются и исчезают без перехода и отображаются чёрными на скриншотах. Повёрнутые экраны, видеостены и макеты с зонами используют обычный путь.",
  'device.ignore_battery.hint': "Для телевизоров и панелей без батареи, плата которых всё равно сообщает фиктивный уровень (например, постоянное «42%, заряжается»). Принудительно очищает показание батареи, чтобы везде, включая оповещения, устройство считалось питающимся от сети. Для устройств с настоящей батареей оставьте выключенным.",
