  'corp.settings.store_shape': "Как устроены ваши магазины? Отдельное рабочее пространство для каждого магазина разделяет магазины. Если ваши магазины — это группы внутри одного рабочего пространства, каждый, кто может редактировать это рабочее пространство, может менять контент слотов каждой группы.",
  'corp.settings.store_triggers': "Триггеры магазинов на экранах головного офиса",
  'corp.settings.policy_allow': "Показывать триггеры магазинов",
  'corp.settings.policy_allow_help': "Триггер магазина показывается поверх плейлиста головного офиса, как и поверх любого другого плейлиста. Магазин, который продолжает посылать сигнал, может перекрывать плейлист головного офиса сколько угодно.",
  'corp.settings.policy_leased': "Ограничить зависшие триггеры до",
