  'corp.settings.policy_leased_help': "Завершает триггер, отправитель которого перестал посылать сигнал. Магазин, который продолжает посылать сигнал, по-прежнему может держать его включённым.",
  'corp.settings.policy_off': "Не показывать триггеры магазинов (по умолчанию)",
  'corp.settings.policy_off_help': "Плейлист головного офиса нельзя перекрыть из магазина. Собственные оповещения магазинов, например об эвакуации, на этих экранах тоже не будут показываться — для них используйте экстренное оповещение. Прежде чем какой-либо экран перейдёт под управление головного офиса, вы увидите, какие триггеры магазинов перестанут показываться.",
  'corp.settings.impact_limited': "Триггеры будут ограничены: {k} в рабочих пространствах: {m}.",
