  'device.ota.hint': "Когда выключено, этому устройству никогда не предлагаются обновления — его обновлениями занимается MDM или оператор. Выключайте для панелей под управлением MDM (например, Pivot/MAXHUB), чтобы приложение никогда не показывало диалог самостоятельной установки.",
