  'live_video.title': "Живое видео",
  'live_video.explain': "Позволяет операторам смотреть живую WebRTC-трансляцию экрана на вкладке «Сейчас воспроизводится» вместо периодических скриншотов. Требуется настроенный на сервере sidecar go2rtc и включение живого видео для каждого экрана. Экраны, которые не могут публиковать видео, продолжают использовать скриншоты.",
