  'live_video.save_failed': "Не удалось обновить настройку живого видео",
  'approval.title': "Согласование контента",
  'approval.explain': "Когда включено, любая публикация в этом рабочем пространстве (плейлисты, презентации, виджеты, макеты, заменённые медиафайлы) сначала требует согласования проверяющим. Черновики никогда не меняют то, что показывают экраны. То, что в эфире сейчас, продолжает воспроизводиться и не требует согласования задним числом.",
  'approval.toggle': "Требовать согласование перед публикацией",
