  'smart.by_rules': "По правилам",
  'smart.edit_rules': "Изменить правила",
  'smart.panel_title': "Умный плейлист",
  'smart.panel_hint': "После публикации этот плейлист обновляется сам при добавлении, тегировании, истечении срока или удалении контента. Изменения правил вступают в силу при публикации. В рабочих пространствах, где требуется согласование, новый подходящий контент ждёт согласованного выпуска; контент, который перестал подходить, сразу убирается с экранов.",
  'smart.empty': "Под эти правила пока ничего не подходит.",
  'smart.empty_hint': "Добавьте теги к контенту в библиотеке или измените правила.",
  'smart.toast.saved': "Правила сохранены. Опубликуйте, чтобы применить их на экранах.",
  'repeat.once': "Раз за цикл",
  'repeat.every_sec': "каждые {n} с",
  'repeat.every_min': "каждые {n} мин",
  'repeat.hint': "Воспроизводить этот элемент чаще: он распределяется по циклу примерно с этим интервалом. Только для последовательного порядка.",
  'repeat.toast_saved': "Сохранено. Опубликуйте, чтобы применить на экранах.",
  'widget.web.interactive': "Интерактивный (киоск самообслуживания)",
  'widget.web.interactive_hint': "Посетители могут нажимать, прокручивать и заполнять формы. Плейлист приостанавливается, пока кто-то пользуется страницей, а после ухода посетителя страница сбрасывается и всё, что он сделал, стирается. Только в полноэкранном режиме. Полная поддержка на Android, нативных плеерах для Windows и Raspberry Pi и на BrightSign; веб-экраны, webOS и Tizen получают ограниченную версию, которая не может стереть данные сайта или заблокировать другие сайты.",
  'widget.web.idle_timeout': "Сбрасывать после стольких секунд без касаний",
  'widget.web.allowed_domains': "Другие сайты, которые могут открывать посетители",
  'widget.web.allowed_domains_ph': "например, checkout.example.com, maps.example.com",
  'widget.web.allowed_domains_hint': "Сайт самой страницы всегда разрешён. Ссылки на любые другие сайты блокируются.",
  'widget.web.home_button': "Показывать кнопку «Домой», когда посетитель уходит со стартовой страницы",
  'widget.web.idle_warning': "Обратный отсчёт «Вы здесь?» перед сбросом",
  'widget.web.idle_warning_off': "Выключено (сбрасывать сразу)",
  'widget.web.idle_warning_sec': "{n} с",
  'widget.web.idle_warning_hint': "Даёт посетителю время нажать и продолжить. Полезно для магазина; на информационной странице можно отключить.",
  'widget.web.wipe_site_data': "Стирать cookie и хранилище сайта после каждого посетителя",
  'widget.web.wipe_site_data_hint': "Отключите для информационных страниц, где нечего защищать (меню, прайс-листы, карты): тогда баннер cookie и выбранный язык сохранятся. Каждый посетитель всё равно получает чистую страницу, историю и данные форм. Хранилище общее для всех веб-страниц на экране, поэтому стирание другого элемента на том же экране очищает и его. Плееры для Windows и Raspberry Pi сохраняют cookie, но не хранилище сайта; BrightSign стирает всегда.",
  'widget.web.keep_consent': "Сохранять выбор согласия на cookie между посетителями",
  'widget.web.keep_consent_hint': "Сохраняются только cookie согласия разрешённых сайтов. Логины, корзины и всё остальное по-прежнему стираются после каждого посетителя. Инструменты согласия, которые хранят выбор в localStorage, а не в cookie, будут спрашивать снова.",
  'widget.web.keep_cookie_names': "Имена других cookie для сохранения",
  'widget.web.keep_cookie_names_ph': "например, shop_consent, cc_*",
  'widget.web.keep_cookie_names_hint': "Распространённые инструменты согласия (Cookiebot, OneTrust, IAB TCF, CookieYes, Complianz, Borlabs, iubenda, Didomi и другие) распознаются автоматически. Символ * в конце соответствует префиксу. Никогда не добавляйте сюда cookie входа или корзины.",
  'widget.web.zoom_hint': "Масштаб в % выше применяется и к интерактивной странице: 150 заставляет десктопный сайт отображаться так, будто экран составляет две трети своего размера.",
  'device.event.web_error': "Сбой веб-страницы",
  'device.event.load_error': "Веб-страница не загрузилась",
  'device.event.http_error': "Веб-страница вернула ошибку",
  'device.event.renderer_gone': "Веб-страница аварийно завершилась",
  'device.event.webview_too_old': "Веб-странице нужна более новая версия WebView",
  'device.caps.web_interactive': "Интерактивные веб-страницы:",
  'device.caps.web_interactive_full': "полная поддержка (сайт открывается в собственном браузере; ссылки за пределы разрешённых сайтов блокируются, а после каждого посетителя всё стирается)",
  'device.caps.web_interactive_framed': "ограниченная поддержка (сайт работает во фрейме: сайты, запрещающие фреймы, остаются пустыми, а экран не может блокировать другие сайты или стирать то, что оставил посетитель, поэтому вход в аккаунт может пережить сброс)",
  'device.caps.web_interactive_none': "не поддерживается (интерактивные страницы отображаются как обычные веб-страницы)",
  'widget.web.support': "На экранах этого рабочего пространства: {full} — полная поддержка, {framed} — ограниченная (без стирания), {none} показывают как обычную страницу.",
  'report.kiosk.title': "Интерактивные сеансы",
