  'nav.platform.rollouts': "Поэтапные выпуски плееров",
  'platform.tab.rollouts': "Поэтапные выпуски плееров",
  'platform.rollouts.title': "Поэтапные выпуски плееров",
  'platform.rollouts.subtitle': "Новые версии плееров доходят до экранов волнами и сами останавливаются, если работают хуже",
  'platform.rollouts.desc': "Новый плеер для Android, Pi или Windows сначала попадает на 10% экранов этой платформы, затем на 50%, затем на все; каждая волна ждёт, пока обновлённые экраны не покажут здоровую работу. Если обновлённые экраны падают или гаснут чаще остальных, выпуск останавливается сам, и вам приходит письмо. Экраны Pi и Windows, получившие остановленную версию, возвращаются на предыдущую. Android нельзя откатить на более старую версию, поэтому там остановка прекращает распространение, а исправить ситуацию можно только более новой сборкой. Экраны на бета-канале и принудительное обновление пропускают волны.",
  'platform.rollouts.disabled': "Волны на этом сервере отключены (OTA_STAGED_ROLLOUT=off): новая версия предлагается всем экранам сразу.",
  'platform.rollouts.empty': "С момента появления этой функции ни одна версия плеера не выпускалась.",
  'platform.rollouts.col.player': "Плеер",
