  'auto.intro': "Позвольте другим системам менять то, что показывают ваши экраны: пожарная панель, Alertus, InformaCast, Zapier, Make или n8n. Каждый хук — это секретный веб-адрес; его вызов поднимает оповещение, запускает триггер, обновляет таблицу или переключает экраны на плейлист.",
