  'auto.hint.mass_notification': "Для систем массового оповещения. Принимает XML CAP 1.2 или JSON от Alertus, InformaCast и подобных систем. Оповещения сопоставляются по собственному ID оповещения отправителя, поэтому повтор или повторная попытка показываются один раз, а отбой завершает оповещение.",
