  'auto.zapier_title': "Zapier, Make и n8n",
  'auto.zapier_intro': "Zapier может запустить Zap, когда здесь что-то происходит (экран уходит в офлайн, поднимается оповещение, публикуется плейлист), а его действия могут поднимать оповещения, переключать плейлисты, запускать триггеры и обновлять таблицы.",
  'auto.zapier_base': "Адрес API для Zapier:",
  'auto.zapier_token': "Подключайтесь с помощью API-токена из «Настройки» → «API-токены». Используйте «Чтение и запись» для событий и таблиц и «Полный (включая команды устройствам)» для действий, которые перехватывают управление экранами.",
