  'auto.mn_explain': "Укажите в своей системе массового оповещения адрес этого хука. Поля для CAP, Alertus и InformaCast определяются автоматически; если ваш отправитель использует другие названия, задайте соответствие ниже.",
  'auto.mapping': "Сопоставление полей (необязательно)",
