  'auto.f.trigger': "Триггер",
  'auto.trigger_note': "Триггер можно запустить через интернет на экранах Raspberry Pi, Windows и Mac, а также на экранах с веб-плеером (браузер, BrightSign, webOS, Vega, iPad). Экраны Android по-прежнему запускают его из собственной сети; экраны Tizen и Roku запустить из хука нельзя.",
