  'auto.f.allow_get_hint': "По умолчанию выключено. Предпросмотр ссылок в мессенджерах и почтовые сканеры открывают любой найденный адрес методом GET, что вызвало бы хук. Включайте только для отправителя, который не умеет отправлять POST.",
