  'simple.help.g1.title': "Привязать экран",
  'simple.help.g1.s1': "На телевизоре, планшете или компьютере, который вы хотите использовать, откройте плеер: установите приложение для Android или откройте страницу /player этого сайта в браузере.",
  'simple.help.g1.s2': "Нет под рукой телевизора? Откройте плеер в другой вкладке браузера, чтобы попробовать.",
  'simple.help.g1.s3': "Плеер покажет 6-значный код. Здесь выберите «Добавить экран» и введите его.",
  'simple.help.g1.s4': "Дайте экрану понятное вам название, например «Витрина».",
  'simple.help.g2.title': "Изменить то, что показывает экран",
  'simple.help.g2.s1': "Выберите «Изменить то, что показывает экран» или нажмите на экран в разделе «Ваши экраны».",
  'simple.help.g2.s2': "Выберите «Заменить», чтобы показывать только новое, или «Добавить», чтобы сохранить то, что уже воспроизводится.",
  'simple.help.g2.s3': "Загрузите фото или видео, выберите ранее загруженные или покажите то же, что и на другом экране.",
  'simple.help.g2.s4': "Экран обновится в течение нескольких секунд.",
  'simple.help.g3.title': "Загрузить фото и видео",
  'simple.help.g3.s1': "Выберите «Загрузить фото» и укажите сколько угодно файлов или перетащите их сюда.",
  'simple.help.g3.s2': "Отметьте экраны, которые должны их показывать, или снимите все отметки, чтобы сохранить файлы на потом.",
  'simple.help.g3.s3': "Фото показываются по 10 секунд каждое; видео воспроизводятся до конца.",
  'simple.help.q1': "Что можно использовать в качестве экрана?",
  'simple.help.a1': "Телевизоры, приставки и планшеты на Android, Fire TV, смарт-телевизоры LG и Samsung, Raspberry Pi, Windows и ChromeOS — или любое устройство с веб-браузером.",
  'simple.help.q2': "Мой экран не меняется. Что проверить?",
  'simple.help.a2': "Убедитесь, что на главной странице экран показывает «Воспроизведение». Если там «Офлайн», проверьте, что устройство включено и подключено к интернету — оно получит ваши изменения, как только восстановит связь.",
  'simple.help.q3': "Что будет, если пропадёт интернет?",
  'simple.help.a3': "Экраны хранят контент локально и продолжают его воспроизводить. Новые изменения поступят, когда связь восстановится.",
  'simple.help.q4': "Какие файлы можно загрузить?",
  'simple.help.a4': "Фото (JPEG, PNG, GIF, WebP) и видео (лучше всего MP4), а также аудио. PDF можно загрузить на странице «Контент» в расширенном режиме.",
  'simple.help.q5': "Как переименовать или удалить экран?",
  'simple.help.a5': "Переключитесь на расширенный режим (справа вверху), откройте «Экраны», нажмите на нужный экран и используйте «Переименовать» или «Удалить» вверху его страницы.",
  'simple.help.q6': "Можно ли показывать разное в разное время суток?",
  'simple.help.a6': "Да — для этого есть «Расписание» в расширенном режиме. В простом режиме экран всегда показывает один и тот же контент, пока вы его не измените.",
  'simple.help.trial_q': "Как работает бесплатный пробный период?",
  'simple.help.trial_a': "Вы получаете 14 дней тарифа Pro со всеми разблокированными функциями, карта не нужна. По окончании вы перейдёте на тариф Free: ничего не удаляется, а экраны сверх лимита тарифа Free приостановятся, пока вы не выберете тариф.",
  'stats.prompt.title': "Помочь узнать, насколько широко используется ScreenTinker?",
  'stats.prompt.body': "Поскольку большинство установок закрытые, мы не знаем, сколько экранов работает. При отправке передаются случайный ID, версия и количество ваших экранов — больше ничего, никогда. Это можно изменить в любой момент в настройках.",
