  'passkey.admin_no_app_url': "Для passkey нужен постоянный публичный адрес сервера, а он не задан. Укажите в APP_URL адрес, которым пользуются люди (например, https://signage.example.com), и перезапустите сервер. Пока этого не сделано, passkey остаются отключёнными, а не привязываются к любому адресу, который указан в запросе.",
