  'migrate.field.password': "Пароль",
  'migrate.field.timezone': "Часовой пояс",
  'migrate.field.region': "Регион",
  'migrate.how.xibo': "В Xibo откройте «Администрирование», затем «Приложения» и добавьте приложение с отмеченным пунктом «Client Credentials». Скопируйте его Client ID и Client Secret. Введите адрес вашей CMS (тот, по которому вы входите), например https://cms.example.com.",
  'migrate.how.yodeck': "В Yodeck откройте «Account Settings», «Advanced Settings», «API Tokens» и создайте токен (тариф Premium или Enterprise). Вставьте его в виде метка:токен. Yodeck не отдаёт через API исходные загруженные изображения и документы: они перечисляются, чтобы вы могли добавить их через импорт из zip. Видео переносятся в той версии, которую воспроизводит Yodeck.",
  'migrate.how.optisigns': "У OptiSigns есть API, но в нём не описан способ скачать ваши файлы, поэтому плейлист придёт пустым. Скачайте свои файлы из OptiSigns и используйте импорт из zip: одна папка на плейлист или файл playlists.csv.",
  'migrate.how.magicinfo': "API MagicINFO перечисляет ваш контент и плейлисты, но в нём не описан способ скачать файлы, поэтому плейлист придёт пустым. Ваши экраны Samsung можно оставить: переключите их на ScreenTinker в меню дисплея (System > Play Via > URL Launcher, на новых моделях он называется Custom App). Скопируйте свои медиафайлы из MagicINFO и используйте импорт из zip: одна папка на плейлист или файл playlists.csv.",
  'migrate.how.screencloud': "В ScreenCloud Studio откройте «Account Settings», затем вкладку «Developer» и создайте токен с правами на чтение. Выберите показанный там регион (EU или US). ScreenCloud хранит правила по времени для отдельных элементов канала; они перечисляются, но не импортируются.",
  'migrate.how.anthias': "Введите адрес вашего устройства Anthias, например http://192.168.1.20. Если вы включили аутентификацию, введите имя пользователя и пароль. Каждое устройство импортируется как один экран с одним плейлистом.",
  'migrate.how.screenly': "В Screenly откройте «Settings», «Security», «Tokens» и добавьте токен. Плейлисты, метки и экраны переносятся; простые правила по дням и времени становятся расписаниями.",
  'migrate.how.generic_zip': "Загрузите zip-архив с вашими медиафайлами. Каждая папка станет плейлистом. По желанию добавьте playlists.csv (столбцы: playlist, file, duration, order) и screens.csv (столбцы: name, group, playlist).",
